panels = [(1, 0.2), (2, 0.9), (3, 0.4), (4, 0.1),
          (5, 0.7), (6, 0.5), (7, 0.3), (8, 0.8)]  # (칸, 난이도)
RATIO = {1: 0.25, 2: 0.5, 3: 0.75, 4: 1.0}

def english_panels(panels, level):
    k = round(len(panels) * RATIO[level])
    easy_first = sorted(panels, key=lambda p: p[1])
    return sorted(no for no, _ in easy_first[:k])

for lv in RATIO:
    print(lv, english_panels(panels, lv))
